import {
  View,
  TouchableOpacity,
  ViewStyle,
  TextStyle,
  FlatList,
} from 'react-native';
import React from 'react';
import styles from './styles';
import {
  IconCheckedRadio,
  IconRadio,
  IconRadioDisable,
} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';

export type GroupData = {
  id: string | number;
  label: string;
};

type Props = {
  data: GroupData[];
  currentValue?: GroupData;
  onPressData: (item: GroupData) => void;
  containerStyle?: ViewStyle;
  itemStyle?: ViewStyle;
  labelStyle?: TextStyle;
  numColumns?: number;
  scrollEnabled?: boolean;
  disable?: boolean;
};
const GroupRadio = ({
  data,
  currentValue,
  onPressData,
  containerStyle,
  itemStyle,
  labelStyle,
  numColumns = 1,
  scrollEnabled = false,
  disable = false,
}: Props) => {
  const checkSelected = (item: GroupData) => {
    return item.id === currentValue?.id;
  };

  const onPressItem = (item: GroupData) => {
    if (checkSelected(item)) return;
    onPressData(item);
  };

  const renderItem = ({item}: {item: GroupData}) => {
    return (
      <TouchableOpacity
        disabled={disable}
        key={item.id}
        style={[styles.viewItem, itemStyle]}
        onPress={() => {
          onPressItem(item);
        }}>
        {checkSelected(item) ? (
          disable ? (
            <IconRadioDisable width={24} height={24} />
          ) : (
            <IconCheckedRadio width={24} height={24} />
          )
        ) : (
          <IconRadio width={24} height={24} />
        )}
        <TextCM
          style={[
            styles.txtName,
            checkSelected(item) && styles.txtSuccessText,
            labelStyle,
          ]}>
          {item.label}
        </TextCM>
      </TouchableOpacity>
    );
  };

  return (
    <View style={[styles.container, containerStyle]}>
      <FlatList
        data={data}
        keyExtractor={item => item.id.toString()}
        renderItem={renderItem}
        contentContainerStyle={styles.flatlistContainer}
        scrollEnabled={scrollEnabled}
        numColumns={numColumns}
      />
    </View>
  );
};

export default GroupRadio;
