import {FC, useState} from 'react';
import {TouchableOpacity, View} from 'react-native';
import styles from '../../styles';
import {useTranslation} from 'react-i18next';
import {colorList} from '../../helper';
import {isEmpty} from 'lodash';
import { SizeDP } from '../../../../constants/Size';
import ButtonCM from '../../../../components/Button';
import TextCM from '../../../../components/Text';
import { RightArrowGrey } from '../../../../assets/images';
import BottomSheetCM from '../../../../components/BottomSheet';

type Props = {
  type: 'text' | 'pen';
  valueSelect: number;
  onChange: (value: number) => void;
  disableButton?: boolean;
};

const ConfigColor: FC<Props> = ({
  type,
  valueSelect,
  onChange,
  disableButton = false,
}) => {
  const {t} = useTranslation();
  const [isVisible, setIsVisiable] = useState<boolean>(false);

  const renderItemListColor = () => {
    return (
      <>
        <View style={styles.ctnListColor}>
          {colorList.map((item, index) => (
            <TouchableOpacity
              onPress={() => onChange(index)}
              key={index}
              style={[
                styles.boxColor,
                {
                  backgroundColor: `rgb(${item})`,
                  borderWidth: index == valueSelect ? SizeDP(4) : 0,
                },
              ]}></TouchableOpacity>
          ))}
        </View>
        {disableButton === false ? (
          <ButtonCM
            label={t('CM.TxtSave')}
            onPress={() => setIsVisiable(false)}
          />
        ) : null}
      </>
    );
  };
  return (
    <>
      <View style={styles.ctnConfigList}>
        <TextCM style={styles.textConfig}>
          {type === 'pen' ? t('AC.colorPen') : t('AC.colorText')}
        </TextCM>
        <TouchableOpacity
          onPress={() => setIsVisiable(true)}
          style={styles.ctnWithArrow}>
          {!isEmpty(colorList) && (
            <View
              style={[
                styles.ctnColor,
                {
                  backgroundColor: `rgb(${colorList[valueSelect]})`,
                },
              ]}></View>
          )}
          <RightArrowGrey width={SizeDP(20)} height={SizeDP(20)} />
        </TouchableOpacity>
      </View>
      <BottomSheetCM
        title={type === 'pen' ? t('AC.colorPen') : t('AC.colorText')}
        isVisible={isVisible}
        onClose={() => setIsVisiable(false)}
        renderContent={renderItemListColor()}
      />
    </>
  );
};

export default ConfigColor;
