import {TouchableOpacity, View} from 'react-native';
import styles from '../../styles';
import React, {FC, useEffect, useState} from 'react';
import {fontImageDigitalList} from '../../helper';
import {isUndefined} from 'lodash';
import {useTranslation} from 'react-i18next';
import GroupRadio, { GroupData } from '../../../../components/GroupRadio';
import TextCM from '../../../../components/Text';
import { RightArrowGrey } from '../../../../assets/images';
import { SizeDP } from '../../../../constants/Size';
import BottomSheetCM from '../../../../components/BottomSheet';

type Props = {
  data: GroupData | undefined;
  onChangeData: (item: GroupData) => void;
};

const ConfigFont: FC<Props> = ({onChangeData, data}) => {
  const {t} = useTranslation();
  const [isVisible, setIsVisiable] = useState<boolean>(false);

  useEffect(() => {
    onChangeData(fontImageDigitalList[1]);
  }, []);

  const handleChangeData = (item: GroupData) => {
    onChangeData(item);
    setIsVisiable(false);
  };

  const renderItemListColor = () => {
    return (
      <GroupRadio
        data={fontImageDigitalList}
        currentValue={data ? data : fontImageDigitalList[0]}
        onPressData={item => handleChangeData(item)}
      />
    );
  };
  return (
    <>
      <View style={styles.ctnConfigList}>
        <TextCM style={styles.textConfig}>{t('AC.fontText')}</TextCM>
        <TouchableOpacity
          onPress={() => setIsVisiable(true)}
          style={styles.ctnWithArrow}>
          <TextCM style={styles.colorTextSelect}>
            {!isUndefined(data) ? data.label : fontImageDigitalList[0].label}
          </TextCM>
          <RightArrowGrey width={SizeDP(20)} height={SizeDP(20)} />
        </TouchableOpacity>
      </View>
      <BottomSheetCM
        title={t('AC.fontText')}
        isVisible={isVisible}
        onClose={() => setIsVisiable(false)}
        renderContent={renderItemListColor()}
      />
    </>
  );
};

export default ConfigFont;
