import {View, Text} from 'react-native';
import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import PicDateView from './components/PicDateView';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import {GroupData} from '../../../../../components/GroupRadio';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import Toast from 'react-native-toast-message';

type Props = {
  data: IDocument;
  toggleModal: () => void;
  isVisible: boolean;
  onExdateSuccess: () => void;
};
const ModalExdateDocument = ({
  data,
  isVisible,
  toggleModal,
  onExdateSuccess,
}: Props) => {
  const {t} = useTranslation();

  const [numberDate, setNumberDate] = useState<GroupData>({
    id: 15,
    label: t('DC.Txt15Day'),
  });

  const DocumentServices = useDocumentServices();

  const onSubmit = () => {
    const body = {
      id: data.id,
      days: numberDate.id,
    };
    try {
      const res = DocumentServices.exDate(body);
      Toast.show({
        type: 'success',
        text1: t('DC.Messages.TxtExdateSuccess'),
      });
      onExdateSuccess();
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    } finally {
      toggleModal();
    }
  };

  const Content = () => {
    return (
      <View style={styles.container}>
        <View style={styles.viewDate}>
          <TextCM style={styles.txtTitle}>{t('DC.TxtTitleExDate')}</TextCM>
          <PicDateView value={numberDate} onPicType={setNumberDate} />
        </View>
        <View style={styles.footer}>
          <ButtonCM
            label={t('CM.BtnConfirm')}
            onPress={onSubmit}
            style={styles.btnFooter}
          />
        </View>
      </View>
    );
  };

  return (
    <>
      <BottomSheetCM
        title={t('DC.TxtExDateDocument')}
        renderContent={<Content />}
        onClose={toggleModal}
        isVisible={isVisible}
      />
    </>
  );
};

export default ModalExdateDocument;
