import {yupResolver} from '@hookform/resolvers/yup';
import React, {useState} from 'react';
import {FormProvider, useForm} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import * as yup from 'yup';
import {IExtendedRecipients} from '../../helper';
import ModalFindRecipient from '../ModalFindRecipient';
import YupTextField from './components/YupTextField';
import styles from './styles';
import {RegexUtils} from '../../../../../utils';
import Toast from 'react-native-toast-message';
import {IFinderRecipient} from '../../../../../model/interface/envelope.interface';
import {IcBlackLeftArrow, IconBlackSearch} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';
import {useAppSelector} from '../../../../../hook/useRedux';

type ModalReplaceRecipientProp = {
  onClose: () => void;
  isVisible: boolean;
  documentId: string;
  recipient: IExtendedRecipients;
  onFetchinng?: () => void;
};

const ModalReplaceRecipient = ({
  documentId,
  recipient,
  onClose,
  isVisible,
  onFetchinng,
}: ModalReplaceRecipientProp) => {
  const {t} = useTranslation();
  const devicesInfo = useAppSelector(state => state.common.devicesInfo);
  const schema = yup.object().shape({
    name: yup.string().trim().required(t('SU.fieldRequired')),
    email: yup
      .string()
      .matches(RegexUtils.FORMAT_EMAIL, t('SU.wrongEmail'))
      .required(t('SU.fieldRequired')),
    phoneNumber: yup
      .string()
      .matches(RegexUtils.REGEX_PHONE_NUMBER, t('SU.wrongPhoneNumber'))
      .required(t('SU.fieldRequired')),
  });
  const insets = useSafeAreaInsets();
  const [showModalFindReplace, setShowModalFindReplace] = useState(false);
  const DocumentServices = useDocumentServices();
  const toggleModalFindReplace = () => {
    setShowModalFindReplace(!showModalFindReplace);
  };

  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      name: recipient?.contact?.name,
      email: recipient?.contact?.email,
      phoneNumber: recipient?.contact?.phone,
    },
  });

  const onSubmit = async () => {
    try {
      const res = await DocumentServices.replaceEnvelopRecipient(
        documentId,
        recipient.id,
        methods.getValues('name').trim(),
        methods.getValues('email'),
        methods.getValues('phoneNumber'),
        devicesInfo,
        null,
      );
      Toast.show({
        type: 'success',
        text1: t('DC.replaceRecipientSuccess'),
      });
      if (onFetchinng) {
        onFetchinng();
      }
    } catch (error) {
    } finally {
      onClose();
    }
  };

  const onSelectedFromModal = (item: IFinderRecipient) => {
    methods.setValue('name', item?.personalName);
    methods.setValue('email', item?.email);
    methods.setValue('phoneNumber', item?.phone);
    toggleModalFindReplace();
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <View style={styles.ctnContainer}>
          <View style={styles.ctnTop} onTouchEnd={onClose} />
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('DC.replaceRecipient')}
              </TextCM>
              <View />
            </View>
            <View style={styles.viewBody}>
              <FormProvider {...methods}>
                <YupTextField
                  controlName={'name'}
                  label={t('DC.typeName')}
                  viewIconRight={<IconBlackSearch width={14} height={16} />}
                  onPressIconRight={toggleModalFindReplace}
                />
                <YupTextField controlName={'email'} label={t('DC.typeEmail')} />
                <YupTextField
                  controlName={'phoneNumber'}
                  label={t('SU.enterPhoneNumber')}
                  keyboardType={'phone-pad'}
                />
                <ButtonCM
                  disabled={!methods.formState.isValid}
                  label={t('CM.BtnConfirm')}
                  onPress={onSubmit}
                />
              </FormProvider>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
      {showModalFindReplace && (
        <ModalFindRecipient
          onClose={toggleModalFindReplace}
          isVisible={showModalFindReplace}
          onSelected={onSelectedFromModal}
        />
      )}
    </Modal>
  );
};

export default ModalReplaceRecipient;
