import {useNavigation, useRoute} from '@react-navigation/native';
import {isEmpty, isUndefined} from 'lodash';
import {useEffect, useRef, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  Dimensions,
  Image,
  ScrollView,
  TouchableOpacity,
  View,
} from 'react-native';
import {ImageOrVideo} from 'react-native-image-crop-picker';
import {SafeAreaView} from 'react-native-safe-area-context';
import SignatureScreen, {SignatureViewRef} from 'react-native-signature-canvas';
import ConfigColor from './component/ConfigColor';
import ConfigFont from './component/ConfigFont';
import ConfigPosition from './component/ConfigPosition';
import ConfigShowText from './component/ConfigShowText';
import ConfigSize from './component/ConfigSize';
import TabsComponent, {TypeTabs} from './component/Tabs';
import {colorList, fontImageDigitalList, positionList} from './helper';
import styles from './styles';
import Toast from 'react-native-toast-message';
import ImageCropPicker from '../../components/ImageCropPicker';
import {accountActions, commonActions} from '../../redux/slices';
import {SizeDP} from '../../constants/Size';
import {Color, String} from '../../constants';
import SwitchCM from '../../components/Switch';
import TextCM from '../../components/Text';
import {View as ViewCM} from 'react-native';
import ButtonCM from '../../components/Button';
import HeaderCM from '../../components/Header/HeaderCM';
import TextFieldCM from '../../components/TextField';
import {useAppDispatch, useAppSelector} from '../../hook/useRedux';
import {GroupData} from '../../components/GroupRadio';
import {DoubArrow, IconGreyDoubArrow, IconNoImage} from '../../assets/images';
import CheckboxCM from '../../components/Checkbox';
import BottomSheetCM from '../../components/BottomSheet';
import {useSettingStore} from '../settings/store/settingStore';
import { useAccountServices } from '../../hook/apiHook/useApi';

const style = `.m-signature-pad--footer {display: none; margin: 0px;}`;

const AddDigitalSignature = () => {
  const route = useRoute<any>();

  const initData = route.params?.data;
  const isNew = route.params?.isNew || false;

  const ref = useRef<SignatureViewRef>(null);
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const dispatch = useAppDispatch();
  const [isDisabled, setIsDisabled] = useState<boolean>(true);
  const accountServices = useAccountServices();
  const [isDisabelBtnClearSignature, setIsDisabelBtnClearSignature] =
    useState<boolean>(true);
  const [isDisabelPad2, setIsDisabelPad2] = useState<boolean>(false);
  const [checked, setChecked] = useState<boolean>(false);
  const [dataWidth, setDataWidth] = useState<number>(320);
  const [dataHeight, setDataHeight] = useState<number>(160);
  const [colorTextSelector, setColorTextSelector] = useState<number>(0);
  const [colorPenSelector, setColorPenSelector] = useState<number>(18);
  const [textDisplay, setTextDisplay] = useState({
    signedBy: true,
    title: true,
    signingDate: true,
  });
  const [selectedTypeTabs, setSelectedTypeTabs] = useState<TypeTabs>(
    TypeTabs.DEVICES,
  );
  const [selectedPads, setSelectedPads] = useState<'pad1' | 'pad2'>('pad1');
  const [visible, setVisible] = useState<boolean>(false);
  const [visiblePreview, setVisiblePreview] = useState<boolean>(false);
  const [imageSelected, setImageSelected] = useState<
    ImageOrVideo | undefined
  >();
  const [imageClearBg, setImageClearBg] = useState<string>('');
  const [imageDrawing, setImageDrawing] = useState<string>('');
  const [scrollEnabled, setScrollEnabled] = useState(true);
  const [switchSelectClearBg, setSwitchSelectClearBg] =
    useState<boolean>(false);
  const [switchSelectChangePenSize, setSwitchSelectChangePenSize] =
    useState<boolean>(false);
  const [fontData, setFontData] = useState<GroupData>();
  const [positionsData, setPositionsData] = useState<GroupData>();
  const [showPrewResult, setShowPrewResult] = useState<string>('');
  const {dataAccount} = useAppSelector(
    state => state.account,
  );
  // const {isReloadingSign} = useAppSelector(state => state.account)
  const {isReloadingSign, setIsReloadingSign} = useSettingStore();
  const [name, setName] = useState('');

  useEffect(() => {
    if (initData) {
      getInitData();
    }
  }, []);

  useEffect(() => {
    ref?.current?.changePenColor(`rgba(${colorList[colorPenSelector]})`);
  }, [colorPenSelector]);

  useEffect(() => {
    if (selectedTypeTabs === TypeTabs.DRAW) {
      setIsDisabelBtnClearSignature(true);
      setSelectedPads('pad1');
    } else {
      setImageClearBg('');
    }
  }, [selectedTypeTabs]);

  const getInitData = () => {
    setName(initData.name);
    setDataWidth(initData.digitalSignature?.w || 320);
    setDataHeight(initData.digitalSignature?.h || 160);
    setPositionsData(
      positionList.find(i => i.id === initData.digitalSignature?.type) ||
        positionList[0],
    );
    setFontData(
      fontImageDigitalList.find(
        i => i.id === initData.digitalSignature?.fieldTextDesign?.font,
      ) || fontImageDigitalList[0],
    );
    const indexColor = colorList.findIndex(
      i => i == initData.digitalSignature?.fieldTextDesign?.color,
    );
    setColorTextSelector(indexColor != -1 ? indexColor : 0);
    setChecked(initData.digitalSignature?.fieldTextDesign?.multiLine || false);
    setTextDisplay(initData.digitalSignature?.fieldTextDesign?.textDisplay);
    setImageSelected({
      data: initData.digitalSignature?.fieldLogoDesign?.value.replace(
        'data:image/png;base64,',
        '',
      ),
    } as ImageOrVideo);
    setIsDisabled(false);
  };
  const handleChangePad = (type: 'pad1' | 'pad2') => {
    if (type === 'pad2') {
      setIsDisabelPad2(true);
      setSwitchSelectChangePenSize(false);
    } else {
      setIsDisabelPad2(false);
    }
    setSelectedPads(type);
    setIsDisabelBtnClearSignature(true);
    setImageDrawing('');
    setIsDisabled(true);
    setScrollEnabled(true);
  };

  const handleSelectImageFromDevices = async () => {
    try {
      const image = (await ImageCropPicker.ChoosePhoto({
        cropping: true,
        includeBase64Enabled: true,
      })) as ImageOrVideo;
      if (image.size > 2000000) {
        Toast.show({
          type: 'error',
          text1: t('AC.TxtAlertMaxImageSize'),
        });
      } else {
        setImageSelected(image);
        setVisible(true);
        setSwitchSelectClearBg(false);
        setImageClearBg('');
      }
    } catch (error) {
    } finally {
    }
  };

  const handleClearBackgroundImage = async (value: boolean) => {
    setSwitchSelectClearBg(value);
    try {
      if (!isEmpty(imageClearBg)) return;
      if (!value) return;
      console.log("truoc khi clear background");
      const imageClearBgData = await accountServices.clearBackground(
        (imageSelected as any)?.data,
      );
      setImageClearBg(imageClearBgData.data);
    } catch (error) {
      console.log(error);
      Toast.show({
        type: 'error',
        text1: t('AC.alert.clearBackgroundErr'),
      });
    }
  };

  const handleSaveImage = () => {
    setVisible(false);
    setIsDisabled(false);
  };

  const handleSignature = (signature: any) => {
    setIsDisabelBtnClearSignature(false);
    setImageDrawing(signature);
    setIsDisabled(false);
  };

  const handleEmpty = () => {
    setIsDisabelBtnClearSignature(true);
  };

  const handleClear = () => {
    setIsDisabelBtnClearSignature(true);
    setIsDisabled(true);
  };

  const handleEnd = () => {
    setScrollEnabled(true);
    ref.current?.readSignature();
  };

  const handleBegin = () => {
    setScrollEnabled(false);
  };

  const changeSwitchPenSize = (value: boolean) => {
    setSwitchSelectChangePenSize(value);
    value ? ref.current?.changePenSize(0, 8) : ref.current?.changePenSize(0, 3);
  };

  const getPositionImageBase64ToPreview = () => {
    if (selectedTypeTabs === TypeTabs.DEVICES) {
      if (switchSelectClearBg) {
        return imageClearBg;
      }
      return (imageSelected as any)?.data;
    } else {
      return imageDrawing.split(',')[1];
    }
  };
  const createRecipient = () => {
    const recipient = {
      contact: {
        id: null,
        name: '' + dataAccount.firstName + dataAccount.lastName,
        email: dataAccount.email,
        phone: null,
        type: null,
      },
      fields: [
        {
          id: '1',
          fieldDesign: {
            id: '1',
            type: positionsData?.id,
            w: dataWidth,
            h: dataHeight,
            fieldLogoDesign: {
              position: (positionsData?.id as string)?.split('')[0],
              size: null,
              required: true,
              value: getPositionImageBase64ToPreview(),
            },
            fieldTextDesign: {
              position: (positionsData?.id as string)?.split('')[1],
              required: true,
              items: null,
              color: colorList[colorTextSelector],
              font: fontData?.id,
              multiLine: checked,
              textDisplay: textDisplay,
            },
          },
        },
      ],
      order: 1,
      recipientsHistory: [],
    };
    return recipient;
  };

  const createRecipientData = () => {
    const recipient = {
      fieldDesign: {
        id: '1',
        type: positionsData?.id,
        w: dataWidth,
        h: dataHeight,
        fieldLogoDesign: {
          position: (positionsData?.id as string)?.split('')[0],
          size: null,
          required: true,
          value: getPositionImageBase64ToPreview(),
        },
        fieldTextDesign: {
          position: (positionsData?.id as string)?.split('')[1],
          required: true,
          items: null,
          color: colorList[colorTextSelector],
          font: fontData?.id,
          multiLine: checked,
          textDisplay: textDisplay,
        },
      },
      name: name.trim(),
      star: false,
    };
    return recipient;
  };

  const handlePreviewDigitalSignature = async () => {
    const recipient = createRecipient();
    try {
      const value = await accountServices.previewImageDesign(recipient);
      setShowPrewResult(value.data);
      setVisiblePreview(true);
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('AC.alert.errShowDataPreview'),
      });
    }
  };

  const handleSaveData = async () => {
    dispatch(commonActions.setIsLoading(true));
    const recipient = createRecipientData();
    const body: {
      id?: number;
      data: any;
    } = {
      data: {
        ...recipient,
        star: initData?.star || isNew,
      },
    };
    if (initData) {
      body.id = initData.id;
    }
    try {
      const res = await accountServices.updateImageDigitalSignature(body);
      setIsReloadingSign(!isReloadingSign);
      dispatch(accountActions.fetchAccount());
      navigation.goBack();
      Toast.show({
        type: 'success',
        text1: isEmpty(initData)
          ? t('AC.alert.createDigitalSignatureSuccess')
          : t('AC.alert.updateDigitalSignatureSuccess'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('AC.alert.errSaveImage'),
      });
    } finally {
      dispatch(commonActions.setIsLoading(false));
    }
  };

  const renderPreviewImageChoose = () => {
    return (
      <View>
        {!isUndefined(imageSelected) && (
          <>
            <View style={{borderRadius: 8, overflow: 'hidden'}}>
              {!switchSelectClearBg ? (
                <Image
                  height={SizeDP(240)}
                  source={{
                    uri:
                      String.PREFIX_IMG_BASE64 + (imageSelected as any)?.data,
                  }}
                />
              ) : (
                <Image
                  height={SizeDP(240)}
                  source={{uri: String.PREFIX_IMG_BASE64 + imageClearBg}}
                />
              )}
            </View>
            <View style={styles.ctnSwitch}>
              <SwitchCM
                isEnabled={switchSelectClearBg}
                onPress={() => handleClearBackgroundImage(!switchSelectClearBg)}
              />
              <TextCM>{t('AC.clearBg')}</TextCM>
            </View>
            <ButtonCM label={t('CM.TxtSave')} onPress={handleSaveImage} />
          </>
        )}
      </View>
    );
  };

  const renderPreviewImage = () => {
    return (
      <>
        <>
          {!isEmpty(showPrewResult) && (
            <ScrollView
              style={{height: (Dimensions.get('screen').height / 3) * 2}}>
              <View style={styles.ctnPrevImage}>
                <Image
                  style={styles.viewImage}
                  resizeMode="contain"
                  height={SizeDP(dataHeight)}
                  width={SizeDP(dataWidth)}
                  source={{uri: String.PREFIX_IMG_BASE64 + showPrewResult}}
                />
              </View>
              <ConfigSize
                type="width"
                data={dataWidth}
                onChangeData={setDataWidth}
                defaultValue={dataWidth}
              />
              <ConfigSize
                type="height"
                data={dataHeight}
                onChangeData={setDataHeight}
                defaultValue={dataHeight}
              />
            </ScrollView>
          )}
        </>
        <ButtonCM
          label={t('CM.BtnClose')}
          onPress={() => setVisiblePreview(false)}
        />
      </>
    );
  };

  return (
    <>
      <HeaderCM
        title={
          isEmpty(initData)
            ? t('AC.addDigitalSignature')
            : t('AC.TxtEditDigitalSignature')
        }
      />
      <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
        <ScrollView scrollEnabled={scrollEnabled} style={{flex: 1}}>
          <ViewCM style={styles.viewInputName}>
            <TextCM style={styles.txtTitle}>{t('AC.titleSign')}</TextCM>
            <TextFieldCM
              value={name}
              onChangeText={setName}
              label={t('AC.TxtNameDigitalSignature')}
              isRequired
              maxLength={100}
            />
          </ViewCM>
          <View style={styles.ctnConfig}>
            <TabsComponent
              selected={selectedTypeTabs}
              onChangeTabs={value => {
                setSelectedTypeTabs(value);
                setImageSelected(undefined);
                setIsDisabled(true);
              }}
            />
            {selectedTypeTabs === TypeTabs.DEVICES && (
              <ViewCM style={styles.viewFormPicImage}>
                <ViewCM style={styles.viewImageHeader}>
                  <ViewCM style={styles.viewTxtSignatureImage}>
                    <TextCM style={styles.txtSignatureImag}>
                      {t('AC.TxtSignatureImage')}
                      <TextCM style={styles.txtRed}> * </TextCM>
                    </TextCM>
                    <TextCM style={styles.txtNote}>
                      {t('AC.TxtMaxImageSize')}
                    </TextCM>
                  </ViewCM>
                  <TextCM style={styles.txtNote}>
                    {t('AC.TxtSupportedFormats')}
                  </TextCM>
                </ViewCM>
                {(!isEmpty(imageClearBg) || !isUndefined(imageSelected)) &&
                !visible ? (
                  <ViewCM style={styles.viewImageChoice}>
                    <Image
                      style={styles.image}
                      source={{
                        uri:
                          String.PREFIX_IMG_BASE64 +
                          (switchSelectClearBg
                            ? imageClearBg
                            : (imageSelected as any)?.data),
                      }}
                    />
                  </ViewCM>
                ) : (
                  <ViewCM style={styles.viewNoImage}>
                    <IconNoImage width={SizeDP(60)} height={SizeDP(60)} />
                  </ViewCM>
                )}

                <TouchableOpacity
                  style={styles.btnUploadImage}
                  onPress={handleSelectImageFromDevices}>
                  <TextCM style={styles.txtUpload}>
                    {!isEmpty(imageClearBg) || !isUndefined(imageSelected)
                      ? t('AC.TxtReload')
                      : t('AC.uploadImage')}
                  </TextCM>
                </TouchableOpacity>
              </ViewCM>
            )}
            {selectedTypeTabs === TypeTabs.DRAW && (
              <View style={styles.ctnDevices}>
                {selectedPads === 'pad1' && (
                  <>
                    <SignatureScreen
                      style={styles.stylesSignatureScreen}
                      ref={ref}
                      onBegin={handleBegin}
                      onEnd={handleEnd}
                      onOK={handleSignature}
                      onEmpty={handleEmpty}
                      onClear={handleClear}
                      autoClear={false}
                      webStyle={style}
                      trimWhitespace={true}
                      imageType="image/png"
                      penColor={`rgba(${colorList[colorPenSelector]})`}
                    />
                    <TextCM style={styles.textPad}>Pad 1</TextCM>
                  </>
                )}
                {selectedPads === 'pad2' && (
                  <>
                    <SignatureScreen
                      style={styles.stylesSignatureScreen}
                      ref={ref}
                      onBegin={handleBegin}
                      onEnd={handleEnd}
                      onOK={handleSignature}
                      onEmpty={handleEmpty}
                      onClear={handleClear}
                      autoClear={false}
                      webStyle={style}
                      penColor={`rgba(${colorList[colorPenSelector]})`}
                    />
                    <TextCM style={styles.textPad}>Pad 2</TextCM>
                  </>
                )}
                <View style={styles.ctnNotiDraw}>
                  <TextCM style={styles.digitalNoti}>{t('AC.padNoti')}</TextCM>
                  <View style={styles.ctnSwitchPad}>
                    <TouchableOpacity
                      onPress={() => handleChangePad('pad1')}
                      disabled={selectedPads === 'pad1'}>
                      {selectedPads === 'pad1' ? (
                        <IconGreyDoubArrow
                          width={SizeDP(20)}
                          height={SizeDP(16)}
                        />
                      ) : (
                        <DoubArrow width={SizeDP(20)} height={SizeDP(16)} />
                      )}
                    </TouchableOpacity>
                    <View style={styles.drawPadLine}></View>
                    <TouchableOpacity
                      disabled={selectedPads === 'pad2'}
                      onPress={() => handleChangePad('pad2')}
                      style={{transform: [{rotate: '180deg'}]}}>
                      {selectedPads === 'pad1' ? (
                        <DoubArrow width={SizeDP(20)} height={SizeDP(16)} />
                      ) : (
                        <IconGreyDoubArrow
                          width={SizeDP(20)}
                          height={SizeDP(16)}
                        />
                      )}
                    </TouchableOpacity>
                  </View>
                </View>
                <View style={styles.ctnChangeAndClear}>
                  <View style={[styles.ctnSwitch, {paddingVertical: 0}]}>
                    <SwitchCM
                      disable={isDisabelPad2}
                      isEnabled={switchSelectChangePenSize}
                      onPress={() =>
                        changeSwitchPenSize(!switchSelectChangePenSize)
                      }
                    />
                    <TextCM>{t('AC.netThanhDam')}</TextCM>
                  </View>
                  <ButtonCM
                    disabled={isDisabelBtnClearSignature}
                    style={[
                      styles.customBtnClear,
                      {
                        backgroundColor: !isDisabelBtnClearSignature
                          ? Color.RedEA4335
                          : Color.textDisableColor,
                      },
                    ]}
                    styleLabel={{
                      color: Color.White,
                    }}
                    label={t('CM.BtnClear')}
                    onPress={() => ref?.current?.clearSignature()}
                  />
                </View>
              </View>
            )}
          </View>
          <View style={styles.seperateView} />
          <View style={styles.ctnConfig}>
            <TextCM style={styles.titleConfig}>{t('AC.setting')}</TextCM>
            <ConfigPosition
              data={positionsData}
              onChangeData={setPositionsData}
            />
            <ConfigFont data={fontData} onChangeData={setFontData} />
            <ConfigSize
              type="width"
              data={dataWidth}
              onChangeData={setDataWidth}
              defaultValue={320}
            />
            <ConfigSize
              type="height"
              data={dataHeight}
              onChangeData={setDataHeight}
              defaultValue={160}
            />
            <ConfigColor
              valueSelect={colorTextSelector}
              onChange={setColorTextSelector}
              type="text"
            />
            <ConfigColor
              valueSelect={colorPenSelector}
              onChange={setColorPenSelector}
              type="pen"
            />
            <View style={styles.ctnConfigList}>
              <TextCM style={styles.textConfig}>{t('AC.downline')}</TextCM>
              <CheckboxCM
                checked={checked}
                onChange={() => setChecked(!checked)}
              />
            </View>
            <ConfigShowText
              valueTextDisplay={textDisplay}
              onChangeTextDisplay={setTextDisplay}
            />
            <TextCM style={styles.textNoti}>{t('AC.noteSizeImage')}</TextCM>
          </View>
        </ScrollView>
        <View style={styles.groupButton}>
          <ButtonCM
            disabled={isDisabled || !name.trim()}
            label={t('AC.showResult')}
            type="white"
            style={styles.customButtonContainer}
            onPress={handlePreviewDigitalSignature}
          />
          <ButtonCM
            disabled={isDisabled || !name.trim()}
            label={t('CM.TxtSave')}
            style={styles.customButtonContainer}
            onPress={handleSaveData}
          />
        </View>
      </SafeAreaView>
      <BottomSheetCM
        title={t('AC.uploadImage')}
        isVisible={visible}
        onClose={() => setVisible(false)}
        renderContent={renderPreviewImageChoose()}
      />

      <BottomSheetCM
        title={t('AC.uploadImage')}
        isVisible={visiblePreview}
        onClose={() => setVisiblePreview(false)}
        renderContent={renderPreviewImage()}
      />
    </>
  );
};

export default AddDigitalSignature;
