import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity} from 'react-native';
import styles from './styles';
import ModalEditInfo from '../ModalEditInfo';
import {useAppSelector} from '../../../../hook/useRedux';
import {DateUtils} from '../../../../utils';
import TextCM from '../../../../components/Text';
import {View as ViewCM} from 'react-native';
import {IconBlueUser, IconOrangePen} from '../../../../assets/images';
import {SizeDP} from '../../../../constants/Size';
import {getNameGender} from './helper';

const AccountDetail = () => {
  const {t} = useTranslation();
  const user = useAppSelector(state => state.account.dataAccount);

  const {firstName, lastName, email, phone, dob, gender, address} = user;

  const name = `${firstName} ${lastName}`;

  const [isShowModalEdit, setIsShowModalEdit] = useState(false);

  const onPressEdit = () => {
    toggleModalEdit();
  };

  const toggleModalEdit = () => {
    setIsShowModalEdit(!isShowModalEdit);
  };

  const DATA_DETAIL = [
    {
      label: t('AI.TxtFullName'),
      value: name,
    },
    {
      label: t('AI.TxtEmail'),
      value: email,
    },
    {
      label: t('AI.TxtPhone'),
      value: phone,
    },
    {
      label: t('AI.TxtBirthday'),
      value: DateUtils.convertDateToDDMMYYYY(dob || ''),
    },
    {
      label: t('AI.TxtGender'),
      value: t(getNameGender(gender)),
    },
    {
      label: t('AI.TxtAddress'),
      value: address,
    },
  ];

  const renderItem = (item: any) => {
    return (
      <ViewCM style={styles.viewItem} key={item.label}>
        <TextCM style={styles.txtLabelItem}>{item.label}</TextCM>
        <ViewCM style={styles.viewTxtItem}>
          <TextCM style={styles.txtItem}>{item.value || '---'}</TextCM>
        </ViewCM>
      </ViewCM>
    );
  };

  return (
    <ViewCM style={styles.container}>
      <ViewCM style={styles.header}>
        <IconBlueUser width={SizeDP(18)} height={SizeDP(18)} />
        <TextCM style={styles.txtHeader}>{t('AI.TxtDetailInfo')}</TextCM>
        <TouchableOpacity onPress={onPressEdit}>
          <IconOrangePen width={SizeDP(18)} height={SizeDP(18)} />
        </TouchableOpacity>
      </ViewCM>
      <ViewCM style={styles.body}>{DATA_DETAIL.map(renderItem)}</ViewCM>
      <ModalEditInfo isVisible={isShowModalEdit} onClose={toggleModalEdit} />
    </ViewCM>
  );
};

export default AccountDetail;
